import org.springframework.boot.*;
import org.springframework.boot.autoconfigure.*;
import org.springframework.context.annotation.Import;
import org.springframework.web.bind.annotation.*;
import org.springframework.http.*;
import java.util.*;
@SpringBootConfiguration
@EnableAutoConfiguration
@Import(Lesson.Web.class)
public class Lesson {
 public static void main(String[] args) { SpringApplication.run(Lesson.class, args); }
 @RestController
 static class Web {
@GetMapping("/broken") String broken() { throw new IllegalStateException("Practice failure"); }
@ExceptionHandler(IllegalStateException.class) ResponseEntity<?> failure() { return ResponseEntity.status(500).body(Map.of("error", "Try again later")); }
 }
}
